param([Parameter(Mandatory)][string]$Msi)
$ErrorActionPreference = 'Stop'
$installer = New-Object -ComObject WindowsInstaller.Installer
$db = $installer.OpenDatabase((Resolve-Path -LiteralPath $Msi).Path, 1)
function Sql([string]$query) {
    try {
        $view = $db.OpenView($query)
        $view.Execute()
        $view.Close()
    } catch { throw "Could not apply MSI upgrade rule: $query ($($_.Exception.Message))" }
}

# Each rebuilt installer can replace an earlier review build with the same public version.
# The reverse (downgrade) range generated by jpackage already excludes its lower bound.
$product = [guid]::NewGuid().ToString('B').ToUpperInvariant()
Sql "UPDATE Property SET Value = '$product' WHERE Property = 'ProductCode'"
$view = $db.OpenView("SELECT * FROM Upgrade WHERE ActionProperty = 'JP_UPGRADABLE_FOUND'")
$view.Execute()
$row = $view.Fetch()
$upgradeFlags = $row.IntegerData(5) -bor 512  # msidbUpgradeAttributesVersionMaxInclusive
$row.GetType().InvokeMember('IntegerData', 'SetProperty', $null, $row, @(5, $upgradeFlags))
$view.Modify(4, $row)  # msidbModifyReplace; Attributes is part of the primary key.
$view.Close()

# FindRelatedProducts sets JP_UPGRADABLE_FOUND before AppSearch in both UI and silent installs.
$uninstall = 'Software\Microsoft\Windows\CurrentVersion\Uninstall\[JP_UPGRADABLE_FOUND]'
foreach ($root in 1, 2) {
    Sql "INSERT INTO RegLocator (Signature_, Root, ``Key``, Name, Type) VALUES ('RpdInstallLocation$root', $root, '$uninstall', 'InstallLocation', 18)"
    Sql "INSERT INTO AppSearch (Property, Signature_) VALUES ('INSTALLDIR', 'RpdInstallLocation$root')"
    Sql "INSERT INTO RegLocator (Signature_, Root, ``Key``, Name, Type) VALUES ('RpdPreviousVersion$root', $root, '$uninstall', 'DisplayVersion', 18)"
    Sql "INSERT INTO AppSearch (Property, Signature_) VALUES ('RPD_PREVIOUS_VERSION', 'RpdPreviousVersion$root')"
}
Sql "INSERT INTO ControlEvent (Dialog_, Control_, Event, Argument, Condition, Ordering) VALUES ('WelcomeDlg', 'Next', 'NewDialog', 'VerifyReadyDlg', 'JP_UPGRADABLE_FOUND AND INSTALLDIR', 20)"
Sql "INSERT INTO ControlEvent (Dialog_, Control_, Event, Argument, Condition, Ordering) VALUES ('VerifyReadyDlg', 'Back', 'NewDialog', 'WelcomeDlg', 'JP_UPGRADABLE_FOUND AND INSTALLDIR', 20)"

# Legacy jpackage MSIs recursively remove INSTALLDIR, which can also contain desk.properties.
# Remove their cleanup marker transactionally before uninstalling the old product.
$view = $db.OpenView("SELECT Component_, Property FROM WixRemoveFolderEx")
$view.Execute()
$row = $view.Fetch()
$component = $row.StringData(1)
$marker = $row.StringData(2)
$view.Close()
# jpackage also records the actual folder in the user's product key. Keep it during same-version repairs.
Sql "INSERT INTO CustomAction (Action, Type, Source, Target) VALUES ('RpdRepairDir', 51, 'INSTALLDIR', '[$marker]')"
foreach ($sequence in 'InstallUISequence','InstallExecuteSequence') {
    Sql "INSERT INTO $sequence (Action, Condition, Sequence) VALUES ('RpdRepairDir', 'Installed AND $marker AND NOT INSTALLDIR', 51)"
}
Sql "UPDATE InstallExecuteSequence SET Condition = 'NOT REMOVE' WHERE Action = 'JpSetARPINSTALLLOCATION'"
Sql 'CREATE TABLE `RemoveRegistry` (`RemoveRegistry` CHAR(72) NOT NULL, `Root` SHORT NOT NULL, `Key` CHAR(255) NOT NULL LOCALIZABLE, `Name` CHAR(255) LOCALIZABLE, `Component_` CHAR(72) NOT NULL PRIMARY KEY `RemoveRegistry`)'
Sql "INSERT INTO RemoveRegistry (RemoveRegistry, Root, ``Key``, Name, Component_) VALUES ('RpdOldCleanup', 1, 'Software\RProbeDesk\RProbeDesk\[RPD_PREVIOUS_VERSION]', '$marker', '$component')"
Sql "UPDATE InstallExecuteSequence SET Sequence = 1501 WHERE Action = 'RemoveRegistryValues'"
Sql "INSERT INTO InstallExecuteSequence (Action, Condition, Sequence) VALUES ('InstallExecute', 'JP_UPGRADABLE_FOUND', 1502)"
Sql "UPDATE InstallExecuteSequence SET Sequence = 1503 WHERE Action = 'RemoveExistingProducts'"
Sql "DELETE FROM WixRemoveFolderEx WHERE Component_ = '$component'"
$db.Commit()
